import os

def clean_drive():
    # Check if drive is writable and you own it
    if not os.path.isdir('/dev/sdX') or not os.path.exists('/dev/sdX'):
        print("Error: Drive not found or unreadable.")
        return
    drive = '/dev/sdX'

    # Delete files recursively
    for root, dirs, files in os.walk(drive):
        for file in files:
            full_path = os.path.join(root, file)
            try:
                os.remove(full_path)
                print(f"[✓] Deleted: {full_path}")
            except FileNotFoundError:
                pass  # Skip if file didn't exist
            except PermissionError:
                pass

    print(f"[✓] Complete. Files deleted.")

