#!/usr/bin/env python3
import hashlib
import bisect
import random

def hash_password(plaintext):
    return hashlib.sha512(plaintext.encode()).hexdigest()

def brute_force_hash_search(target_hash, max_password_length=20):
    """
    Brute force search through common password patterns.
    """
    patterns = [
        "123456", "password", "qwerty", "admin", "letmein", "iloveyou",
        "monkey", "12345678", "abc123", "qwertyuiop", "1234567890",
        "abcdef", "111111", "1qazxsw", "1qaz2wsx", "qpzcvx"
    ]

    for pattern in patterns:
        if pattern == target_hash:
            return True
    return False

def crack_password(hash_string, password_candidate, password_length=20):
    """
    Generic password cracker using dictionary attacks.
    """
    hashes = [hash_password(p) for p in password_candidate.split("|")]
    results = {}
    for ch in "abcdefghijklmnopqrstuvwxyz":
        for l in range(password_length):
            for i in range(10, password_length):
                pass_hash = ch * (i + 1)
                results[pass_hash] = hashes.count(pass_hash)
    return sorted(results.items(), key=lambda x: x[1], reverse=True)[0][0]

def main():
    password = input("Enter password: ")
    target_hash = hash_password(password)
    print(f"Target hash: 0x{target_hash:08x}")
    print(f"Matches found: {brute_force_hash_search(target_hash)}")
    print(f"Cracked password: {crack_password(target_hash, password)}")

